.loader { display: flex; align-items: flex-end; justify-content: space-between; gap: calc(var(--loader-size) * .06); width: var(--loader-size); height: calc(var(--loader-size) * .65); padding-bottom: calc(var(--loader-size) * .05); border-bottom: calc(var(--loader-size) * .025) solid color-mix(in srgb, var(--loader-color) 40%, transparent); box-sizing: border-box; }
.loader span { flex: 1; height: 100%; border-radius: calc(var(--loader-size) * .03) calc(var(--loader-size) * .03) 0 0; background: linear-gradient(to top, var(--loader-color), var(--loader-secondary-color)); transform-origin: bottom center; animation: twGrowBar calc(var(--loader-speed) * 1.8) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .18); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .54); }
@keyframes twGrowBar { 0%, 100% { transform: scaleY(.18); } 50% { transform: scaleY(1); } }

tailwind:
{/* keyframes twGrowBar: scaleY(.18) <-> scaleY(1) from the bottom */}
<div className="flex h-20 w-30 items-end justify-between gap-2 border-b-[3px] border-indigo-500/40 pb-1.5">
  {[0, 180, 360, 540].map((delay) => (
    <span
      key={delay}
      className="h-full flex-1 origin-bottom animate-[twGrowBar_1.8s_ease-in-out_infinite] rounded-t bg-gradient-to-t from-indigo-500 to-cyan-400"
      style={{ animationDelay: delay + "ms" }}
    />
  ))}
</div>
